#!/usr/bin/env node
// Installs the local pre-commit and commit-msg hooks. Git does not track .git/hooks,
// so this script is the tracked source of truth. Re-run after cloning: npm run hooks:install
import { execFileSync } from "node:child_process";
import { chmodSync, mkdirSync, writeFileSync } from "node:fs";
import path from "node:path";

export const HOOK_CONTENT = `#!/bin/sh
# Generated by scripts/install_hooks.mjs. Re-install with: npm run hooks:install
# Bypass once: git commit --no-verify

if [ -d ".projectmem" ] && command -v pjm >/dev/null 2>&1; then
    # Churn fires on every active file because the tool fixes the threshold at four
    # changes in 30 days, so this hook hides churn lines and the empty summary that
    # follows. Stale memories, failed attempts and open issues still print.
    MEMORY_CHECK="$(pjm precheck --level warn 2>&1 | grep -vE 'HIGH CHURN|May indicate unresolved|warning\\(s\\)\\. Review before committing' || true)"
    if printf '%s\\n' "$MEMORY_CHECK" | grep -qE 'WARN|^  x '; then
        printf '%s\\n' "$MEMORY_CHECK"
    fi
fi

if [ -f package.json ]; then
    CHECK_LOG="\${TMPDIR:-/tmp}/galway-pre-commit.log"
    if ! npm run check:lint --silent >"$CHECK_LOG" 2>&1; then
        cat "$CHECK_LOG"
        echo "Pre-commit lint failed. Fix the errors or use git commit --no-verify."
        exit 1
    fi
    STAGED="$(git diff --cached --name-only)"
    TEST_FILES="$(printf '%s\\n' "$STAGED" | grep -E '^tests/[^/]+\\.test\\.mjs$' || true)"
    if printf '%s\\n' "$STAGED" | grep -Eq '^(src/|scripts/|index\\.html|package(-lock)?\\.json|tests/helpers/)'; then
        if ! npm test --silent >"$CHECK_LOG" 2>&1; then
            tail -60 "$CHECK_LOG"
            echo "Pre-commit tests failed. Fix the failures or use git commit --no-verify."
            exit 1
        fi
    else
        if printf '%s\\n' "$STAGED" | grep -Eq '\\.md$' && ! printf '%s\\n' "$TEST_FILES" | grep -qx 'tests/repo_rules.test.mjs'; then
            TEST_FILES="$(printf '%s\\n%s\\n' "$TEST_FILES" "tests/repo_rules.test.mjs" | sed '/^$/d')"
        fi
        if [ -n "$TEST_FILES" ]; then
            if ! node --test $TEST_FILES >"$CHECK_LOG" 2>&1; then
                tail -60 "$CHECK_LOG"
                echo "Pre-commit tests failed. Fix the failures or use git commit --no-verify."
                exit 1
            fi
        fi
    fi
    rm -f "$CHECK_LOG"
fi
`;

export const COMMIT_MSG_HOOK_CONTENT = `#!/bin/sh
# Generated by scripts/install_hooks.mjs. Re-install with: npm run hooks:install
# Enforces Chris Beams' commit guidelines and zero em-dashes (U+2014).

node --input-type=module - "$1" <<'EOF'
import { readFileSync } from "node:fs";

const raw = readFileSync(process.argv[2], "utf8");
const scissor = raw.indexOf("# ------------------------ >8 ------------------------");
const visible = (scissor === -1 ? raw : raw.slice(0, scissor))
  .split(/\\r?\\n/)
  .filter((line) => !line.startsWith("#"));
while (visible.length > 0 && visible[visible.length - 1].trim() === "") {
  visible.pop();
}
if (visible.length === 0) {
  console.error("commit-msg: empty commit message.");
  process.exit(1);
}

const subject = visible[0];
const autoPrefixes = ["Merge ", "Revert ", "fixup! ", "squash! "];
if (autoPrefixes.some((prefix) => subject.startsWith(prefix))) {
  process.exit(0);
}

const errors = [];
if (visible.join("\\n").includes("\\u2014")) {
  errors.push("commit message must not contain literal em-dashes (U+2014).");
}
if (subject.length > 50) {
  errors.push(\`subject exceeds 50 chars (\${subject.length}): "\${subject}"\`);
}
if (/^[a-z]/.test(subject)) {
  errors.push(\`subject must start with a capital letter: "\${subject}"\`);
}
if (subject.endsWith(".")) {
  errors.push(\`subject must not end with a period: "\${subject}"\`);
}
if (visible.length > 1) {
  if (visible[1] !== "") {
    errors.push("separate subject from body with a blank line.");
  }
  for (let i = 2; i < visible.length; i += 1) {
    const line = visible[i];
    if (line.length > 72 && !/https?:\\/\\//.test(line)) {
      errors.push(\`body line \${i + 1} exceeds 72 chars (\${line.length}): "\${line}"\`);
    }
  }
}

if (errors.length > 0) {
  for (const err of errors) console.error(\`commit-msg: \${err}\`);
  process.exit(1);
}
EOF
`;

export function resolveHookPath(exec = execFileSync, hookName = "pre-commit") {
  const hooksDir = exec("git", ["rev-parse", "--git-path", "hooks"], { encoding: "utf8" }).trim();
  return path.resolve(hooksDir, hookName);
}

export function installHooks({ exec = execFileSync, log = console.log } = {}) {
  const target = resolveHookPath(exec, "pre-commit");
  const commitMsgTarget = resolveHookPath(exec, "commit-msg");
  mkdirSync(path.dirname(target), { recursive: true });
  writeFileSync(target, HOOK_CONTENT, "utf8");
  chmodSync(target, 0o755);
  writeFileSync(commitMsgTarget, COMMIT_MSG_HOOK_CONTENT, "utf8");
  chmodSync(commitMsgTarget, 0o755);
  log(`Installed pre-commit hook at ${target}`);
  log(`Installed commit-msg hook at ${commitMsgTarget}`);
  return target;
}

if (process.argv[1] && import.meta.url === `file://${path.resolve(process.argv[1])}`) {
  installHooks();
}
